-- ════════════════════════════════════════════════════════════════════════════
-- Visionary X Operations — REMOVE ALL USERS EXCEPT SUPER ADMINS
--
-- Removes every user who does not have the Super Admin role, with their employee
-- profile, skills, roles, sessions, login links, 2FA codes, project memberships,
-- task assignments, time logs, leave, attendance, calendar invitations and
-- notifications. Their comments and work submissions are deleted too (both
-- require an author). Everything else they touched (clients, projects, tasks,
-- history) stays; the "created by / approved by" name on those becomes blank.
-- Tasks they owned become unassigned.
--
-- Keeps: Super Admin account(s) and ALL business data.
-- Safety: if no Super Admin exists, nothing is deleted.
-- Cannot be undone — back up first (scripts/backup.sh).
-- ════════════════════════════════════════════════════════════════════════════
PRAGMA defer_foreign_keys = true;

-- Preview: who will be removed
SELECT email, name, status FROM users WHERE id IN (SELECT u.id FROM users u WHERE u.id NOT IN (SELECT ur.user_id FROM user_roles ur JOIN roles r ON r.id = ur.role_id WHERE r.key = 'super_admin') AND EXISTS (SELECT 1 FROM user_roles ur JOIN roles r ON r.id = ur.role_id WHERE r.key = 'super_admin'));

